package com.example.starter.plan.model;

/**
 * 区段维护封锁状态：当前仅有 ACTIVE（已生效）。
 * 登记操作只有在全部相交已发布计划于同一事务内处理完毕后才写入 ACTIVE；
 * 登记失败不产生封锁记录，因此不存在中间持久化状态。
 */
public enum WorkBlockStatus {
    ACTIVE
}

package com.example.starter.plan.model;

/**
 * 封锁登记事务内对受影响计划实际执行的处理结果类型（不可变历史）。
 * CANCELLED：原计划被撤销；RESCHEDULED：原计划被整单改签，关联指向后继新计划。
 */
public enum BlockClearanceAction {
    CANCELLED,
    RESCHEDULED
}

package com.example.starter.plan.model;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 区段维护封锁窗口，UTC 左闭右开 [startUtc, endUtc)，相邻端点不冲突。
 *
 * @param id        主键
 * @param blockKey  封锁业务键，全局唯一
 * @param opDate    运营日期（Asia/Shanghai 日历日），窗口必须完全落在该日内
 * @param sectionId 被封锁区段 ID
 * @param startUtc  封锁开始时刻（含），UTC
