        createPlan(nA, occ("G5", sameSection, iso(11), iso(11, 30)));
        createPlan(nB, occ("G6", sameSection, iso(11, 15), iso(11, 45)));
        // oldA/oldB 位于 section，与 sameSection 不同，无法用它们登记 sameSection 封锁；
